CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY, github_id text UNIQUE, email text, name text NOT NULL, avatar_url text, plan text NOT NULL DEFAULT 'free', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS github_tokens(user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, token_enc text NOT NULL, scopes text NOT NULL, updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS projects(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, owner text NOT NULL, repo text NOT NULL, repo_url text NOT NULL, visibility text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS runs(id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, commit_sha text NOT NULL DEFAULT '', status text NOT NULL, stage text NOT NULL, progress real NOT NULL DEFAULT 0, options jsonb NOT NULL, usage jsonb NOT NULL, error jsonb, storyboard_dirty boolean DEFAULT false, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz);
CREATE TABLE IF NOT EXISTS run_events(id bigserial PRIMARY KEY, run_id uuid NOT NULL REFERENCES runs(id) ON DELETE CASCADE, stage text NOT NULL, level text NOT NULL, message text NOT NULL, progress real NOT NULL, ts timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS run_events_run_id ON run_events(run_id);
CREATE TABLE IF NOT EXISTS artifacts(id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES runs(id) ON DELETE CASCADE, kind text NOT NULL, storage_key text NOT NULL, content_type text NOT NULL, bytes bigint NOT NULL, meta jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS shares(id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES runs(id) ON DELETE CASCADE, slug text UNIQUE NOT NULL, is_public boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS usage_counters(user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, month text NOT NULL, runs integer NOT NULL DEFAULT 0, render_seconds integer NOT NULL DEFAULT 0, PRIMARY KEY(user_id,month));
